/*
 * Pro tips
 * - A palindrome equals its reversal; String.equals compares content, unlike ==.
 * - Compare exactly as supplied: this solution does not ignore spaces, punctuation, or case.
 * - Check a singleton, empty input, and a mismatch at either end.
 * - Complexity: O(n) time and O(n) auxiliary space. For basic characters, inward pointers offer an O(1)-space alternative.
 */

import java.util.Scanner;

class Solution {
    public static boolean isPalindrome(String s) {
        // Reverse the string and compare
        String reversed = new StringBuilder(s).reverse().toString();
        return s.equals(reversed);
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        String s = scanner.nextLine();
        scanner.close();
        boolean res = isPalindrome(s);
        System.out.println(res);
    }
}
